public class BookTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Book a = new Book("Clean Code", "9780132350884");
        Book b = new Book("Clean Code (2nd printing)", "9780132350884");
        Book c = new Book("Clean Code", "9999999999999");

        check("same isbn, different titles -> equal", true, a.equals(b));
        check("a book equals itself", true, a.equals(a));
        check("different isbn -> not equal", false, a.equals(c));
        check("equals(null) is false", false, a.equals(null));
        check("not equal to a plain String", false, a.equals("9780132350884"));
        check("equal books share a hash code", true, a.hashCode() == b.hashCode());

        java.util.HashSet<Book> shelf = new java.util.HashSet<>();
        shelf.add(a);
        shelf.add(b);
        shelf.add(c);
        check("HashSet dedupes by isbn (3 adds -> 2 books)", 2, shelf.size());
        check("HashSet contains a same-isbn probe", true,
                shelf.contains(new Book("any title", "9780132350884")));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

